// Fail closed: exact raw Notion bytes only. Handshake never enters storage.
const output=[];
for (const item of $input.all()) {
  const p=item.json ?? {};
  const raw = typeof p.body === 'string' ? p.body
    : typeof p.rawBody === 'string' ? p.rawBody : null;
  if (!raw || raw.length > 60000) throw new Error('RAW_BODY_REQUIRED');
  let parsed;
  try { parsed=JSON.parse(raw); }
  catch { throw new Error('INVALID_JSON'); }
  if (parsed && typeof parsed==='object' && typeof parsed.verification_token==='string') {
    continue; // Notion subscription handshake: never persist or log the token.
  }
  const headers=p.headers ?? {};
  const signature=headers['x-notion-signature'] ?? headers['X-Notion-Signature'];
  if(typeof signature!=='string' || !/^sha256=[a-fA-F0-9]{64}$/.test(signature)) {
    throw new Error('NOTION_SIGNATURE_REQUIRED');
  }
  output.push({json:{raw_body:raw,signature}});
}
return output;
